  ('bg_deep_space', 'background-color: #010208; background-image: radial-gradient(circle, rgba(255,255,255,0.9) 0 1px, transparent 2px), radial-gradient(circle, rgba(128,190,255,0.65) 0 1px, transparent 2px), radial-gradient(ellipse at center, #101634 0%, #03040d 56%, #000 100%); background-size: 90px 90px, 145px 145px, 100% 100%; background-position: 0 0, 40px 60px, 50% 50%; animation: starFieldDrift 18s linear infinite;', 'Layered star fields drift through a deep-space profile scene.'),
  ('bg_god_rays', 'background-color: #271500; background-image: radial-gradient(ellipse at 50% 42%, rgba(255,255,220,0.95) 0%, rgba(255,213,74,0.52) 18%, transparent 52%), repeating-conic-gradient(from -18deg at 50% 28%, rgba(255,244,174,0.72) 0deg 7deg, rgba(255,162,0,0.08) 9deg 18deg), linear-gradient(120deg, #4a1e00, #d68a00, #4a1e00); background-size: 140% 140%, 160% 160%, 220% 100%; animation: godRaysTurn 7s ease-in-out infinite;', 'Sweeping golden beams and radiant dust announce a prestige profile.'),
  ('bg_matrix', 'background-color: #001006; background-image: linear-gradient(rgba(0,255,91,0.16) 1px, transparent 1px), linear-gradient(90deg, rgba(0,255,91,0.12) 1px, transparent 1px), radial-gradient(ellipse at top, rgba(0,255,91,0.18), transparent 62%); background-size: 32px 32px, 32px 32px, 100% 100%; animation: digitalGridScroll 5s linear infinite;', 'A scrolling green data grid with a digital core glow.'),
  ('bg_neon_grid', 'background-color: #07070d; background-image: linear-gradient(rgba(255,0,193,0.28) 1px, transparent 1px), linear-gradient(90deg, rgba(0,255,249,0.28) 1px, transparent 1px), radial-gradient(ellipse at bottom, rgba(145,70,255,0.3), transparent 65%); background-size: 40px 40px, 40px 40px, 100% 100%; animation: neonGridFlow 7s linear infinite;', 'An animated cyan-magenta grid shifts across a neon horizon.'),
  ('bg_ocean_void', 'background-color: #000; background-image: radial-gradient(circle at 52% 46%, #00060a 0 20%, #001827 38%, #00618a 46%, #00111d 60%, #000 78%); background-size: 130% 130%; animation: voidFieldDrift 7.8s ease-in-out infinite reverse;', 'A dark core bends a cold blue oceanic horizon.'),
  ('bg_sunset', 'background-color: #351242; background-image: radial-gradient(ellipse at 75% 25%, rgba(255,210,133,0.76), transparent 42%), linear-gradient(125deg, #592b84, #e64f74, #ff9b68, #592b84); background-size: 170% 170%, 240% 100%; animation: sunsetDrift 10s ease-in-out infinite;', 'Layered sunset light drifts across warm violet and coral bands.'),
