  ('lb_magma', 'background-color: #3a0800; background-image: radial-gradient(circle at 20% 50%, rgba(255,232,120,0.9) 0 2%, transparent 14%), linear-gradient(105deg, #4b0800, #f12711, #ffcf4a, #7a1000, #ff6b00, #4b0800); background-size: 140% 140%, 260% 100%; border: 1px solid #ff6b1a; box-shadow: inset 0 0 18px rgba(80,0,0,0.72), 0 0 12px rgba(255,72,0,0.34); color: #fff !important; animation: magmaFlow 5s linear infinite;', 'Molten veins and ember light flow through your leaderboard row.'),
