  ('lb_void', 'background-color: #000; background-image: radial-gradient(ellipse at 50% 50%, #000 0 22%, #080511 38%, #482775 47%, #090511 54%, #000 75%); background-size: 145% 190%; border: 1px solid rgba(186,151,255,0.58); color: #fff !important; animation: voidRowPulse 4.2s ease-in-out infinite;', 'A black center bends cold light across your leaderboard row.'),
